DELETE FROM user_roles;

-- Assign admin users to Admin role (roleId=1)
INSERT INTO user_roles (userId, roleId) 
SELECT id, 1 FROM users WHERE role = 'admin';

-- Assign staff users to Staff role (roleId=2)
INSERT INTO user_roles (userId, roleId) 
SELECT id, 2 FROM users WHERE role = 'staff';

-- Assign parent users to Parent role (roleId=3)
INSERT INTO user_roles (userId, roleId) 
SELECT id, 3 FROM users WHERE role = 'parent';

